steps.eval:
(() => {
        window.__etnParse = () => {
  const content = document.querySelector('.md-field--editing .cm-content');
  const view = content?.cmTile?.root?.view ?? null;
  if (view === null) return null;
  const values = view.state.values ?? [];
  const lang = values.find((v) => v && typeof v === 'object' && v.tree && v.context);
  const live = values.find((v) => v && typeof v === 'object' && typeof v.size === 'number' && typeof v.iter === 'function' && !('markers' in v));
  const collapse = values.find((v) => v && typeof v === 'object' && v.markers && typeof v.markers.iter === 'function');
  if (!lang || !live || !collapse) return null;
  let decorations = 0;
  for (let it = live.iter(); it.value !== null; it.next()) decorations += 1;
  let markers = 0;
  for (let it = collapse.markers.iter(); it.value !== null; it.next()) markers += 1;
  return { docLen: view.state.doc.length, treeLen: lang.context.treeLen, decorations, markers, caret: view.state.selection.main.head };
};
        window.__poll = async (fn, tries = 80) => { for (let i = 0; i < tries; i += 1) { const value = fn(); if (value !== null && value !== undefined && value !== false) return value; await new Promise((resolve) => setTimeout(resolve, 25)); } return fn(); };
        return true;
      })()

